{
  "tasks": [
    {
      "task_id": "T01",
      "title": "已完成任务的项目工时Top2",
      "business_question": "按项目汇总已完成任务的工时总和，并降序取前两名。注意：仅统计状态为“已完成”的任务；若某项目无已完成任务或工时缺失，保留该项目分组（指标为空）。",
      "priority": "P0",
      "priority_reason": "删除后无法回答核心决策问题（哪些项目的已完成工时最多），直接对应所有核心需求C01-C04。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0003",
                "operator": "eq",
                "value": "已完成"
              }
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0004",
                "alias": "total_hours"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        },
        {
          "step_id": "S03",
          "operation": "top_n",
          "params": {
            "field": "total_hours",
            "direction": "desc",
            "n": 2
          }
        }
      ]
    }
  ]
}
